require('js_asset.js');

var fuzazujian = {
    name: 'fuzazujian',
    aodPos: 0,
    aodMinute: 0,
    editInfo: 0,

    onDestory: function(event) {
        FontId = null;
        StringId = null;
        PicId = null;
        return 0;
    },

    onEvent: function(event) {
        print('onEvent ' + event);
        switch(event)
        {
            case WindowEvent.winTop:
            case WindowEvent.winResume:
            case WindowEvent.winReenter:
            case WindowEvent.minTimeout:
            case WindowEvent.secTimeout:
            case WindowEvent.winRepaint:
            case WindowEvent.timeChange:
                this.draw();
                this.drawTimePos();
            break;
        }
        return 0;
    },

    drawTimePos: function()
    {
        if(this.aodMinute != this.wfInfo.min) {
            this.aodMinute = this.wfInfo.min;
            this.aodPos++;
            var posArray = [[0, 0], [0, 2], [0, 4], [0, 6], [2, 6], [4, 6], [6, 6], [6, 4], [6, 2], [6, 0],
                            [6, -2], [6, -4], [6, -6], [4, -6], [2, -6], [0, -6], [-2, -6], [-4, -6], [-6, -6],
                            [-6, -4], [-6, -2], [-6, 0], [-6, 2], [-6, 4], [-6, 6], [-4, 4], [-2, 2]];
            var index = this.aodPos%27;

            var x = posArray[index][0];
            var y = posArray[index][1];

            this.par.x = x;
            this.par.y = y;
        }
    },

    drawTime: function()
    {
        var angle = 0;
        //设置时针
        if(WatchfaceUpdata.hour & this.wfInfo.updataFlag)
        {
            angle = (this.wfInfo.hour * 3600 + this.wfInfo.min * 60)/12;
            angle = angle << 0; //取整
            this.Pichour.setAngle(angle);
        }
        //设置分针
        if(WatchfaceUpdata.min & this.wfInfo.updataFlag)
        {
            angle = this.wfInfo.min * 60 + this.wfInfo.sec;
            angle = angle << 0; //取整
            this.Picminute.setAngle(angle);
        }
    },


    readUserData: function()
    {
        var bytes = new Object;
        var flag = 0;

        FileManager().readFile({
            filePath:'../../files/data.bin',
            success: function (res)
            {
                print('readFile data.bin success callback ' + res.data.byteLength);
                bytes = res;
                flag = 1;
            },
            fail: function (code){ print('readFile data.bin fail callback, error code' + code); },
            complete: function(){ print('readFile data.bin complete callback'); }
        });

        if (flag > 0) {
            //初始化自定义信息
            this.initEditInfo(bytes);
        }
    },

    initEditInfo: function(bytes)
    {
        var value = new Uint8Array(bytes.data); //将数据转成uint8数组
        if(bytes.data.byteLength >= 16)
        {
            this.editInfo.wfStyle = value[0];
            this.editInfo.timeStyle = value[1];
            this.editInfo.colorNum = (value[12]<<0)+(value[13]<<8)+(value[14]<<16)+(value[15]<<24);
            var colorNum = (bytes.data.byteLength - 16)/4;
            colorNum = colorNum << 0; //取整
            if (colorNum > this.editInfo.colorNum) {
                colorNum = this.editInfo.colorNum;
            }
            if (colorNum > 20) {
                colorNum = 20;
            }

            this.editInfo.colorNum = colorNum;
            for (var i = 0;i < colorNum;i++) {
                this.editInfo.color[i] = (value[16+i*4+0]<<0)+(value[16+i*4+1]<<8)+(value[16+i*4+2]<<16)+(value[16+i*4+3]<<24);
            }
        }
    },


    draw: function()
    {
        this.drawTime();
    },

    init: function(par)
    {
        ImageRelativePath("../");
        //获得表盘参数信息
        this.wfInfo = Watchface();
        this.aodMinute = this.wfInfo.min;
        this.editInfo = new Object;
        this.editInfo.wfStyle = 0;
        this.editInfo.timeStyle = 0;
        this.editInfo.colorNum = 0;
        this.editInfo.color = new Array(20);
        this.readUserData();

        //显示时分数字
        this.Pichour = Image(par, PicId.Picic_hand_hour, 212, 68);
        this.Pichour.setPivot(21,165);
        this.Picminute = Image(par, PicId.Picic_hand_minute, 212, 18);
        this.Picminute.setPivot(21,215);

        //设置显示
        this.draw();

        return 0;
    },

    onCreate: function(par, hor_res, ver_res) {
        this.hor_max = hor_res;
        this.ver_max = ver_res;
        var fixedPage = View(par, 0, 0, hor_res, ver_res);
        var pageStyle = {
            'main:default': {
                'bg-color': 0x000000,
                'border-side': 0x00,
                'radius': 0,
                'pad-all': 0,
            }
        };
        fixedPage.setLocalStyle(pageStyle);
        this.par = fixedPage;
        this.init(fixedPage);

        return fixedPage;
    }
}

!subwm.registerSubWindow(fuzazujian);
